Think: Now I have the current date (2026-01-28). I need to compute the age in days for each file date and create temp_workspace/file_age.csv with columns filename, parsed_date, and age_days. I'll use awk to calculate the difference between the current date and each file date.

Act: bash

```bash
awk -F',' '{
    split($2, date_parts, "-");
    file_year = date_parts[1];
    file_month = date_parts[2];
    file_day = date_parts[3];

    current_date = "2026-01-28";
    split(current_date, current_parts, "-");
    current_year = current_parts[1];
    current_month = current_parts[2];
    current_day = current_parts[3];

    # Convert dates to days since epoch for calculation
    file_days = (file_year - 1970) * 365 + int((file_year - 1969) / 4) - int((file_year - 1901) / 100) + int((file_year - 1601) / 400);
    current_days = (current_year - 1970) * 365 + int((current_year - 1969) / 4) - int((current_year - 1901) / 100) + int((current_year - 1601) / 400);

    # Add days for months
    months[1] = 31; months[2] = 28; months[3] = 31; months[4] = 30; months[5] = 31; months[6] = 30;
    months[7] = 31; months[8] = 31; months[9] = 30; months[10] = 31; months[11] = 30; months[12] = 31;

    for(i = 1; i < file_month; i++) file_days += months[i];
    for(i = 1; i < current_month; i++) current_days += months[i];

    file_days += file_day;
    current_days += current_day;

    age_days = current_days - file_days;

    print $1 "," $2 "," age_days;
}' temp_workspace/file_dates.csv > temp_workspace/file_age.csv
